/// Şablondaki dosya yolları.
Iterable<String> get templatePaths => _encoded.keys;

/// Şablon dosyasının ham baytları; yoksa `null`.
///
/// Görsel gibi ikili dosyalar için; metin dosyaları için
/// [templateFile] kullanın.
List<int>? templateBytes(String path) {
  final encoded = _encoded[path];
  if (encoded == null) return null;
  return base64.decode(encoded);
}

/// Şablon dosyasının metni; yoksa `null`.
String? templateFile(String path) {
  final bytes = templateBytes(path);
  if (bytes == null) return null;
  return utf8.decode(bytes);
}
